chnitt<select id="font-weight"><option value="default">Original</option><option value="regular">Normal</option><option value="bold">Fett</option></select></label><div class="studio-grid-two"><label>Ausrichtung<select id="text-align"><option value="default">Original</option><option value="left">Links</option><option value="center">Mitte</option><option value="right">Rechts</option></select></label><label>Zeilenabstand<select id="line-height"><option value="default">Original</option><option value="compact">Kompakt</option><option value="normal">Normal</option><option value="wide">Luftig</option></select></label></div><div class="studio-grid-two"><label>Schriftstil<select id="font-style"><option value="default">Original</option><option value="italic">Kursiv</option><option value="normal">Normal</option></select></label><label>Farbe<select id="text-color"><option value="default">Original</option><option value="green">Akzentfarbe</option><option value="dark">Dunkel</option><option value="gold">Highlight</option><option value="cream">Creme</option></select></label></div></details></div><label id="image-wrap" class="advanced-field" hidden>Bild auswählen<select id="image"></select></label><details id="image-settings" hidden><summary>Bildbeschreibung &amp; Ausschnitt</summary><label>Bildbeschreibung<input id="image-alt" maxlength="200"></label><label>Bildausschnitt<select id="image-position"><option value="default">Original</option><option value="center">Mitte</option><option value="top">Oben</option><option value="bottom">Unten</option><option value="left">Links</option><option value="right">Rechts</option></select></label></details><div id="media-library" hidden><label>Medien suchen<input id="media-search" type="search" placeholder="Bildname …"></label><div id="media-grid"></div></div><div class="studio-upload" id="upload-wrap" hidden><label>Neues Foto<input id="upload-file" type="file" accept="image/jpeg,image/png,image/webp"></label><label>Bildname<input id="upload-name" type="text" maxlength="120"></label><button id="upload" type="button" class="secondary">Foto hochladen</button><p class="small">Automatisch als WebP optimiert.</p></div><div id="unit-controls" hidden></div><div class="studio-format-row"><button id="reset-field" class="secondary">Original wiederherstellen</button><button id="remove-field" class="secondary studio-danger">× Entfernen</button></div></details><details class="studio-panel" id="blocks-panel"><summary>Bausteine bearbeiten</summary><p class="small">Bearbeite den ausgewählten Abschnitt. Verschieben direkt auf der Website oder über Struktur.</p><div id="block-list"></div><div id="block-editor" hidden><div class="studio-format-row"><button id="block-duplicate" class="secondary">Duplizieren</button><button id="block-focus" class="secondary">Auf Seite zeigen</button><button id="block-delete" class="secondary">Entfernen</button></div><label id="block-title-label">Überschrift<input id="block-title" maxlength="120"></label><label id="block-body-label">Text<textarea id="block-body" rows="5"></textarea></label><div id="block-format" class="quick-format"><span>Textgestaltung</span><div class="studio-grid-two"><label>Textbereich<select id="block-format-part"><option value="title">Überschrift</option><option value="body">Text</option></select></label><label>Schriftart<select id="block-font"><option value="default">Website-Standard</option><option value="sans">Arial</option><option value="modern">Systemschrift</option><option value="serif">Georgia</option><option value="humanist">Trebuchet MS</option></select></label></div><div class="studio-grid-two"><label>Größe (px)<input id="block-size" type="number" min="12" max="96" step="1" placeholder="Standard"></label><label>Farbe<select id="block-color"><option value="default">Original</option><option value="green">Akzentfarbe</option><option value="dark">Dunkel</option><option value="gold">Highlight</option><option value="cream">Creme</option></select></label></div><div class="studio-format-row"><button type="button" id="block-bold" class="secondary" aria-pressed="false"><b>B</b></button><button type="button" id="block-italic" class="secondary" aria-pressed="false"><i>I</i></button><button type="button" data-block-align="left" class="secondary">Links</button><button type="button" data-block-align="center" class="secondary">Mitte</button><button type="button" data-block-align="right" class="secondary">Rechts</button></div></div><label>Stil<select id="block-tone"><option value="light">Hell</option><option value="cream">Creme</option><option value="green">Akzentfarbe</option></select></label><label>Position<select id="block-anchor"></select></label><div class="builder-layout-panel"><h3>Größe &amp; Position</h3><p class="small">Nutze die Griffe direkt im Bild oder ändere die Werte. Alles bleibt im Seitenbereich.</p><div class="layout-device-tabs"><button type="button" data-layout-device="desktop" aria-pressed="true">Desktop</button><button type="button" data-layout-device="mobile" aria-pressed="false">Smartphone</button></div><label>Breite <output id="layout-width-label">100 %</output><input type="range" id="layout-width" min="35" max="100" step="5" value="100"></label><label>Horizontal <output id="layout-x-label">0 %</output><input type="range" id="layout-x" min="0" max="65" step="5" value="0"></label><label>Abstand nach oben <output id="layout-top-label">0 px</output><input type="range" id="layout-top" min="0" max="160" step="8" value="0"></label><div class="studio-format-row"><button id="layout-left" class="secondary" type="button">Links</button><button id="layout-center" class="secondary" type="button">Mitte</button><button id="layout-right" class="secondary" type="button">Rechts</button></div><button id="layout-reset" class="secondary" type="button">Position zurücksetzen</button></div><label>Abschnittabstand<select id="block-spacing"><option value="normal">Normal</option><option value="compact">Kompakt</option><option value="wide">Groß